INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q001', 'speaking', 'Read Aloud', '[{"en": "Credit Cards are a ubiquitous form of payment that have revolutionised the way we conduct transactions.", "zh": "信用卡是一种无处不在的支付方式，它彻底改变了我们进行交易的方式。"}, {"en": "With a credit card, individuals can make purchases without having to carry cash or worry about the availability of funds.", "zh": "有了信用卡，人们可以进行购物，而不必随身携带现金，也不必担心资金是否充足。"}, {"en": "Credit cards also offer a range of benefits such as cashback rewards, travel points, and purchase protection.", "zh": "信用卡还提供一系列福利，例如现金返还奖励、旅行积分和购物保障。"}]', '[{"vid": "w_q001_0", "term": "ubiquitous", "zh": "无处不在的，普遍存在的", "addedBy": "auto"}, {"vid": "w_q001_1", "term": "revolutionise", "zh": "彻底改变，带来革命性变革", "addedBy": "auto"}, {"vid": "w_q001_2", "term": "conduct transactions", "zh": "进行交易", "addedBy": "auto"}, {"vid": "w_q001_3", "term": "availability of funds", "zh": "资金是否充足，资金可用性", "addedBy": "auto"}, {"vid": "w_q001_4", "term": "cashback rewards", "zh": "现金返还奖励", "addedBy": "auto"}, {"vid": "w_q001_5", "term": "purchase protection", "zh": "购物保障", "addedBy": "auto"}, {"vid": "w_q001_6", "term": "a range of", "zh": "一系列的", "addedBy": "auto"}]', '', 'auto', id, '2026-09-18T03:44:27.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q002', 'speaking', 'Read Aloud', '[{"en": "The main production of soft drink was started in 1830''s.", "zh": "软饮料的大规模生产开始于19世纪30年代。"}, {"en": "Since then, from those experimental beginning, there was an evolution until in 1781 when the world''s first cola-flavoured beverage was introduced.", "zh": "从那时起，经过最初的实验性尝试，饮料工业不断演变，直到世界上第一款可乐味饮料问世。"}, {"en": "These drinks were called soft drinks, only to separate them from hard alcoholic drinks.", "zh": "这些饮料之所以被称为“软饮料”，只是为了将它们与“硬性”酒精饮料区分开来。"}, {"en": "Today, soft drink is more favourite refreshment drink than tea, coffee, juice, etc.", "zh": "如今，软饮料比茶、咖啡、果汁等更受欢迎，成为人们首选的解渴饮品。"}]', '[{"vid": "w_q002_0", "term": "experimental", "zh": "实验性的", "addedBy": "auto"}, {"vid": "w_q002_1", "term": "evolution", "zh": "演变，演化", "addedBy": "auto"}, {"vid": "w_q002_2", "term": "cola-flavoured", "zh": "可乐味的", "addedBy": "auto"}, {"vid": "w_q002_3", "term": "beverage", "zh": "饮料（较正式）", "addedBy": "auto"}, {"vid": "w_q002_4", "term": "refreshment", "zh": "提神饮料，茶点", "addedBy": "auto"}]', '原文年份1781与前文1830年代开始生产矛盾，疑为笔误（可乐类饮料实际诞生于19世纪80年代前后）', 'auto', id, '2026-09-18T03:44:28.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q003', 'speaking', 'Read Aloud', '[{"en": "Regular exercise releases brain chemicals key for memory, concentration, and mental sharpness at the same time as lifting your mood, and lowering stress and anxiety all of which contribute to brain health.", "zh": "规律运动会释放出对记忆力、专注力和思维敏锐度至关重要的脑内化学物质，同时还能提升情绪、降低压力和焦虑感，而这些都有助于大脑健康。"}, {"en": "Studies show that regular exercise helps you manage complex tasks, organise and razor-sharpen your focus which is great for those long revision sessions or particularly complex exam questions.", "zh": "研究表明，规律运动有助于你处理复杂任务、整理思路，并让注意力变得高度集中，这对于长时间的复习或应对特别复杂的考题都非常有帮助。"}]', '[{"vid": "w_q003_0", "term": "mental sharpness", "zh": "思维敏锐度", "addedBy": "auto"}, {"vid": "w_q003_1", "term": "contribute to", "zh": "有助于，促成", "addedBy": "auto"}, {"vid": "w_q003_2", "term": "razor-sharpen", "zh": "使变得极其敏锐（源自razor-sharp）", "addedBy": "auto"}, {"vid": "w_q003_3", "term": "revision", "zh": "复习（英式用法）", "addedBy": "auto"}]', '', 'auto', id, '2026-09-18T03:44:29.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q004', 'speaking', 'Read Aloud', '[{"en": "This time the University is running a series of workshops for final year students on how to do well in interviews.", "zh": "这次，学校将为应届毕业生举办一系列研讨会，教他们如何在面试中表现出色。"}, {"en": "These sessions will help participants prepare effectively for and perform at their best during later job interviews.", "zh": "这些活动将帮助参与者为之后的求职面试做好充分准备，并在面试中发挥出最佳水平。"}, {"en": "The workshop tutors have an excellent record of success in helping students acquire the positions they desire.", "zh": "这些研讨会的导师在帮助学生获得心仪职位方面有着出色的成功业绩。"}]', '[{"vid": "w_q004_0", "term": "workshop", "zh": "研讨会，工作坊", "addedBy": "auto"}, {"vid": "w_q004_1", "term": "final year students", "zh": "应届毕业生，大四学生", "addedBy": "auto"}, {"vid": "w_q004_2", "term": "perform at your best", "zh": "发挥出最佳水平", "addedBy": "auto"}, {"vid": "w_q004_3", "term": "tutor", "zh": "导师，指导者", "addedBy": "auto"}, {"vid": "w_q004_4", "term": "record of success", "zh": "成功记录，业绩", "addedBy": "auto"}, {"vid": "w_q004_5", "term": "acquire", "zh": "获得，取得", "addedBy": "auto"}]', '', 'auto', id, '2026-09-18T03:44:30.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q005', 'speaking', 'Read Aloud', '[{"en": "For graduates looking to give something back, volunteering, either in the UK or overseas, is a popular option.", "zh": "对于想要回馈社会的毕业生来说，无论是在英国国内还是去海外做志愿者，都是一个受欢迎的选择。"}, {"en": "Voluntary projects can cost anything from nothing up to a few thousand pounds, and with that in mind it is essential to look into the project carefully before signing on the dotted line.", "zh": "志愿项目的花费可能从分文不取到高达几千英镑不等，考虑到这一点，在正式签约之前仔细了解清楚该项目就显得至关重要。"}]', '[{"vid": "w_q005_0", "term": "give something back", "zh": "回馈（社会）", "addedBy": "auto"}, {"vid": "w_q005_1", "term": "voluntary", "zh": "自愿的，志愿性质的", "addedBy": "auto"}, {"vid": "w_q005_2", "term": "look into", "zh": "调查，仔细了解", "addedBy": "auto"}, {"vid": "w_q005_3", "term": "with that in mind", "zh": "考虑到这一点", "addedBy": "auto"}, {"vid": "w_q005_4", "term": "sign on the dotted line", "zh": "正式签约，签字画押", "addedBy": "auto"}]', '', 'auto', id, '2026-09-18T03:44:31.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q006', 'speaking', 'Read Aloud', '[{"en": "Schools host parent teacher conferences four times a year and it is important for families to attend.", "zh": "学校每年举办四次家长会，家庭成员出席这些会议是很重要的。"}, {"en": "This is your chance to meet with teachers and ask questions about your child''s progress.", "zh": "这是你与老师见面、就孩子的学习进展提出问题的机会。"}, {"en": "It can be helpful to write down questions ahead of time.", "zh": "提前把问题写下来会很有帮助。"}]', '[{"vid": "w_q006_0", "term": "parent-teacher conference", "zh": "家长会", "addedBy": "auto"}, {"vid": "w_q006_1", "term": "host", "zh": "举办，主办（活动）", "addedBy": "auto"}, {"vid": "w_q006_2", "term": "ahead of time", "zh": "提前，事先", "addedBy": "auto"}]', '', 'auto', id, '2026-09-18T03:44:32.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q007', 'speaking', 'Read Aloud', '[{"en": "Like coffee, plain tea contains just a couple of calories per cup and no sugar.", "zh": "和咖啡一样，未加任何调料的纯茶每杯只含有几卡路里的热量，且不含糖分。"}, {"en": "But what''s added in it can change that situation.", "zh": "但是往里面添加的东西会改变这种情况。"}, {"en": "A medium sweet tea and a large iced latte from fast food restaurants both pack about seven teaspoons of sugar.", "zh": "快餐店里一杯中杯甜茶和一杯大杯冰拿铁，都含有大约七茶匙的糖。"}, {"en": "However, the American Heart Association recommends no more than six teaspoons for the whole day.", "zh": "然而，美国心脏协会建议，每人每天的糖摄入量不应超过六茶匙。"}]', '[{"vid": "w_q007_0", "term": "plain", "zh": "原味的，不加调料的", "addedBy": "auto"}, {"vid": "w_q007_1", "term": "pack", "zh": "含有大量……（非正式用法）", "addedBy": "auto"}, {"vid": "w_q007_2", "term": "American Heart Association", "zh": "美国心脏协会", "addedBy": "auto"}, {"vid": "w_q007_3", "term": "teaspoon", "zh": "茶匙（计量单位）", "addedBy": "auto"}]', '', 'auto', id, '2026-09-18T03:44:33.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q008', 'speaking', 'Read Aloud', '[{"en": "The most significant difference between an eating disorder and disordered eating is whether or not a person''s symptoms and experiences align with the criteria defined by the American Psychiatric Association.", "zh": "饮食失调症（eating disorder）与紊乱饮食行为（disordered eating）之间最显著的区别在于，一个人的症状和经历是否符合美国精神病学会所定义的标准。"}, {"en": "The term \"disordered eating\" is a descriptive phrase, not a diagnosis.", "zh": "“紊乱饮食行为”这一说法只是一种描述性表达，并不是一个诊断名称。"}]', '[{"vid": "w_q008_0", "term": "eating disorder", "zh": "饮食失调症（医学诊断名称）", "addedBy": "auto"}, {"vid": "w_q008_1", "term": "disordered eating", "zh": "紊乱饮食行为（非诊断性描述）", "addedBy": "auto"}, {"vid": "w_q008_2", "term": "align with", "zh": "与……相符，与……一致", "addedBy": "auto"}, {"vid": "w_q008_3", "term": "criteria", "zh": "标准，准则（criterion的复数形式）", "addedBy": "auto"}, {"vid": "w_q008_4", "term": "American Psychiatric Association", "zh": "美国精神病学会", "addedBy": "auto"}, {"vid": "w_q008_5", "term": "descriptive", "zh": "描述性的", "addedBy": "auto"}, {"vid": "w_q008_6", "term": "diagnosis", "zh": "诊断", "addedBy": "auto"}]', '', 'auto', id, '2026-09-18T04:06:03.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q009', 'speaking', 'Read Aloud', '[{"en": "Association between meatless diet and depression:", "zh": "无肉饮食与抑郁症之间的关联："}, {"en": "participants who excluded meat from their diet were found to have a higher prevalence of depressive episodes as compared to participants who consumed meat.", "zh": "研究发现，在饮食中不吃肉的参与者，其抑郁发作的发生率高于食肉的参与者。"}, {"en": "This association is independent of socioeconomic, lifestyle factors, and nutrient deficiencies.", "zh": "这种关联与社会经济因素、生活方式因素以及营养缺乏无关（即排除这些因素影响后仍然存在）。"}]', '[{"vid": "w_q009_0", "term": "association", "zh": "关联，关系（统计/研究术语）", "addedBy": "auto"}, {"vid": "w_q009_1", "term": "meatless diet", "zh": "无肉饮食，素食", "addedBy": "auto"}, {"vid": "w_q009_2", "term": "prevalence", "zh": "发生率，流行率", "addedBy": "auto"}, {"vid": "w_q009_3", "term": "depressive episode", "zh": "抑郁发作（精神医学术语）", "addedBy": "auto"}, {"vid": "w_q009_4", "term": "as compared to", "zh": "与……相比", "addedBy": "auto"}, {"vid": "w_q009_5", "term": "independent of", "zh": "与……无关，不受……影响", "addedBy": "auto"}, {"vid": "w_q009_6", "term": "socioeconomic", "zh": "社会经济的", "addedBy": "auto"}, {"vid": "w_q009_7", "term": "nutrient deficiency", "zh": "营养缺乏", "addedBy": "auto"}]', '', 'auto', id, '2026-09-18T04:16:44.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q010', 'speaking', 'Read Aloud', '[{"en": "Television is bound to have a tremendous impact on a child.", "zh": "电视必然会对孩子产生巨大的影响。"}, {"en": "When a parent is concerned about the effects of television, he should consider several things: what TV offers the child in terms of information and knowledge, how many hours a week a youngster his age should watch television, the impact of violence and sex, and the influence of commercials.", "zh": "当家长担心电视带来的影响时，应该考虑几个方面：电视在信息和知识层面能给孩子提供什么，像他这个年龄段的孩子每周应该看多少小时电视，暴力和性内容的影响，以及广告的影响。"}]', '[{"vid": "w_q010_0", "term": "bound to", "zh": "必然会，肯定会（习语）", "addedBy": "auto"}, {"vid": "w_q010_1", "term": "tremendous", "zh": "巨大的，极大的", "addedBy": "auto"}, {"vid": "w_q010_2", "term": "in terms of", "zh": "在……方面，从……角度", "addedBy": "auto"}, {"vid": "w_q010_3", "term": "youngster", "zh": "年轻人，孩子（口语化）", "addedBy": "auto"}, {"vid": "w_q010_4", "term": "commercial", "zh": "（电视）广告（名词，与形容词“商业的”区分）", "addedBy": "auto"}]', '', 'auto', id, '2026-09-19T00:29:31.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q011', 'speaking', 'Read Aloud', '[{"en": "There are three main interpretations of the English Revolution.", "zh": "关于英国革命，主要存在三种解读。"}, {"en": "The longest lasting interpretation was that the Revolution was an almost inevitable outcome of an age old power struggle between parliament and crown.", "zh": "存在时间最久的一种解读认为，这场革命几乎是议会与王权之间历时已久的权力斗争所导致的必然结果。"}, {"en": "The second sees it as a class struggle, and a lead up to the French and other revolutions.", "zh": "第二种解读将其视为一场阶级斗争，是通向法国大革命及其他革命的前奏。"}, {"en": "Finally, the third interpretation sees the other two as too fixed, not allowing for unpredictability, and that the outcome could have gone either way.", "zh": "最后，第三种解读则认为前两种解读过于固定化，没有为不可预测性留出空间，认为革命的结果本来完全可能走向另一个方向。"}]', '[{"vid": "w_q011_0", "term": "interpretation", "zh": "解读，解释（历史学术语）", "addedBy": "auto"}, {"vid": "w_q011_1", "term": "inevitable", "zh": "不可避免的，必然的", "addedBy": "auto"}, {"vid": "w_q011_2", "term": "age-old", "zh": "历时已久的，古老的", "addedBy": "auto"}, {"vid": "w_q011_3", "term": "power struggle", "zh": "权力斗争", "addedBy": "auto"}, {"vid": "w_q011_4", "term": "parliament", "zh": "议会（英国国会）", "addedBy": "auto"}, {"vid": "w_q011_5", "term": "crown", "zh": "王权，君主制（此处为引申义，非字面“王冠”）", "addedBy": "auto"}, {"vid": "w_q011_6", "term": "class struggle", "zh": "阶级斗争", "addedBy": "auto"}, {"vid": "w_q011_7", "term": "a lead up to", "zh": "……的前奏，导致……的前期阶段", "addedBy": "auto"}, {"vid": "w_q011_8", "term": "unpredictability", "zh": "不可预测性", "addedBy": "auto"}, {"vid": "w_q011_9", "term": "could have gone either way", "zh": "本可能走向任一方向（虚拟语气表不确定性）", "addedBy": "auto"}]', '', 'auto', id, '2026-09-19T00:31:22.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q012', 'speaking', 'Read Aloud', '[{"en": "Even though our computers are now better than 15 years ago, they still malfunction between 11 and 20 per cent of the time, a new study concludes.", "zh": "一项新的研究得出结论：尽管现在的电脑比化千前有了很大改进，它们仍有约11%到20%的时间会出现故障。"}, {"en": "The researchers behind the study therefore find that there are major gains to be achieved for society by rethinking the systems and involving users more in their development.", "zh": "因此，这项研究背后的研究人员认为，通过重新思考这些系统、并让用户更多地参与到开发过程中，社会可以从中获得巨大的收益。"}]', '[{"vid": "w_q012_0", "term": "malfunction", "zh": "出故障，故障（动词/名词）", "addedBy": "auto"}, {"vid": "w_q012_1", "term": "researchers behind the study", "zh": "该研究背后的研究人员", "addedBy": "auto"}, {"vid": "w_q012_2", "term": "major gains", "zh": "巨大的收益", "addedBy": "auto"}, {"vid": "w_q012_3", "term": "rethink", "zh": "重新思考", "addedBy": "auto"}, {"vid": "w_q012_4", "term": "involve...in", "zh": "让……参与到……中", "addedBy": "auto"}]', '', 'auto', id, '2026-09-19T00:35:16.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q013', 'speaking', 'Read Aloud', '[{"en": "One of the complex agricultural problems is the issue of food waste.", "zh": "食物浪费是农业领域中一个复杂的问题。"}, {"en": "Food waste refers to the discarding of edible food at various stages of the food supply chain, from production to consumption.", "zh": "食物浪费指的是在食品供应链的各个环节——从生产到消费——丢弃本可食用食物的行为。"}, {"en": "This not only represents a significant loss of resources but also has environmental implications, such as greenhouse gas emissions from decomposing food waste in landfills.", "zh": "这不仅代表着资源的重大损失，还带来了环境方面的影响，例如填埋场中腽烂的食物垃圾会产生温室气体排放。"}]', '[{"vid": "w_q013_0", "term": "agricultural", "zh": "农业的", "addedBy": "auto"}, {"vid": "w_q013_1", "term": "discarding", "zh": "丢弃，抛弃（discard的动名词形式）", "addedBy": "auto"}, {"vid": "w_q013_2", "term": "edible", "zh": "可食用的", "addedBy": "auto"}, {"vid": "w_q013_3", "term": "food supply chain", "zh": "食品供应链", "addedBy": "auto"}, {"vid": "w_q013_4", "term": "environmental implications", "zh": "环境方面的影响/后果", "addedBy": "auto"}, {"vid": "w_q013_5", "term": "greenhouse gas emissions", "zh": "温室气体排放", "addedBy": "auto"}, {"vid": "w_q013_6", "term": "decomposing", "zh": "腽烂、分解中（decompose的现在分词）", "addedBy": "auto"}, {"vid": "w_q013_7", "term": "landfill", "zh": "垃圾填埋场", "addedBy": "auto"}]', '', 'auto', id, '2026-09-19T00:37:55.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
INSERT INTO questions (id, type, subtype, sentences, vocab, notes, source, created_by, created_at) SELECT 'q014', 'speaking', 'Read Aloud', '[{"en": "More and more people are choosing to live in cities.", "zh": "越来越多的人选择在城市生活。"}, {"en": "They offer better opportunities, better services, and sanctuary from conflict and the effects of climate change influences.", "zh": "城市提供了更好的机会、更好的服务，以及免受冲绨和气候变化影响的庸护所。"}, {"en": "Yet large numbers of people are unable for various reasons to move to cities-skills mismatches, reluctance to sell land at a loss, and sometimes because of explicit policy restrictions that limit people''s movement within countries.", "zh": "然而，由于种种原因，大量人口无法迁往城市——比如技能不匹配、不愿以低价出售土地，有时还因为明确的政策限制了人们在国内的迁移。"}]', '[{"vid": "w_q014_0", "term": "sanctuary", "zh": "庸护所，避难所", "addedBy": "auto"}, {"vid": "w_q014_1", "term": "reluctance", "zh": "不愿意，勉强", "addedBy": "auto"}, {"vid": "w_q014_2", "term": "sell at a loss", "zh": "亏本出售", "addedBy": "auto"}, {"vid": "w_q014_3", "term": "explicit policy restrictions", "zh": "明确的政策限制", "addedBy": "auto"}, {"vid": "w_q014_4", "term": "skills mismatch", "zh": "技能不匹配（劳动经济学术语）", "addedBy": "auto"}]', '原文中“skills is matches”应为笔误，根据上下文认为应为“skills mismatches”（技能不匹配）', 'auto', id, '2026-09-19T00:43:19.000Z' FROM users WHERE username = 'Gbtj' LIMIT 1;
